def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(size, separators):
        result = []
        start = 0
        for p in separators + [size]:
            if start < p:
                result.append((start, p))
            start = p + 1
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)

    seeds = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in (0, 8):
                        seeds.setdefault(color, set()).add((ri, ci))

    paints = {}
    for color, points in seeds.items():
        # Connect the extreme markers on each shared row or column.
        for r in range(len(rb)):
            cs = [c for rr, c in points if rr == r]
            if len(cs) >= 2:
                for c in range(min(cs), max(cs) + 1):
                    paints.setdefault((r, c), set()).add(color)
        for c in range(len(cb)):
            rs = [r for r, cc in points if cc == c]
            if len(rs) >= 2:
                for r in range(min(rs), max(rs) + 1):
                    paints.setdefault((r, c), set()).add(color)

    out = [row[:] for row in grid]
    for (ri, ci), colors in paints.items():
        color = 6 if len(colors) > 1 else next(iter(colors))
        r0, r1 = rb[ri]
        c0, c1 = cb[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color

    return out
